//! Private native inverse cubic-map prototype. No global arithmetic dispatch.
use crate::{ifma8::Ifma8,Fq,FqConfig,FpConfig,G2Affine};
use core::{arch::x86_64::*,marker::PhantomData};
const MASK:u64=(1<<52)-1;
pub const INVERSE_BETA:Fq=Fq::from_decimal("2203960485148121921418603742825762020974279258880205651966");
pub const BETA:Fq=Fq::from_decimal("21888242871839275220042445260109153167277707414472061641714758635765020556616");
const fn words()->[u64;4]{let text=b"2203960485148121921418603742825762020974279258880205651966";let mut out=[0u64;4];let mut k=0;while k<text.len(){let mut carry=(text[k]-b'0')as u128;let mut j=0;while j<4{let v=(out[j]as u128)*10+carry;out[j]=v as u64;carry=v>>64;j+=1;}assert!(carry==0);k+=1;}out}
const fn split4(x:[u64;4])->[u64;4]{let mut out=[0u64;4];let mut j=0;while j<4{let pos=j*52;let w=pos/64;let off=pos%64;let mut value=x[w]>>off;if off!=0&&w<3{value|=x[w+1]<<(64-off);}out[j]=value&MASK;j+=1;}assert!(x[3]>>16==0);out}
const fn quotient()->[u64;4]{let mut rem=words();let mut q=[0u64;5];let mut step=0;while step<260{rem=crate::portable::add4(rem,rem).0;let ge=!crate::portable::less(rem,FqConfig::P);if ge{rem=crate::portable::sub4(rem,FqConfig::P).0;}let mut carry=ge as u64;let mut j=0;while j<5{let v=(q[j]<<1)|carry;q[j]=v&MASK;carry=v>>52;j+=1;}assert!(carry==0);step+=1;}assert!(q[4]==0);[q[0],q[1],q[2],q[3]]}
const FACTOR:[u64;4]=split4(words());const QUOTIENT:[u64;4]=quotient();
impl Ifma8<FqConfig,true>{
    /// Multiply normalized numerical R256 words <=2p by canonical beta².
    #[inline(always)]
    pub fn mul_inverse_phi_fixed(&self)->Self{unsafe{
        let zero=_mm512_setzero_si512();let mask=_mm512_set1_epi64(MASK as i64);
        let factor=FACTOR.map(|v|_mm512_set1_epi64(v as i64));let quotient=QUOTIENT.map(|v|_mm512_set1_epi64(v as i64));
        let p=crate::FqConfig::P;let p:[__m512i;5]=core::array::from_fn(|j|{let bit=j*52;let w=bit/64;let off=bit%64;let mut v=p[w]>>off;if off!=0&&w<3{v|=p[w+1]<<(64-off);}_mm512_set1_epi64((v&MASK)as i64)});
        let mut high=[zero;6];for i in 0..5{for j in 0..4{let k=i+j;if k==3{high[0]=_mm512_madd52hi_epu64(high[0],self.0[i],quotient[j]);}else if k>=4{high[k-4]=_mm512_madd52lo_epu64(high[k-4],self.0[i],quotient[j]);high[k-3]=_mm512_madd52hi_epu64(high[k-3],self.0[i],quotient[j]);}}}
        for j in 0..5{high[j+1]=_mm512_add_epi64(high[j+1],_mm512_srli_epi64::<52>(high[j]));high[j]=_mm512_and_si512(high[j],mask);}let q=[high[1],high[2],high[3],high[4]];
        let mut out=[zero;5];for i in 0..5{for j in 0..4{let k=i+j;if k>4{continue;}out[k]=_mm512_madd52lo_epu64(out[k],self.0[i],factor[j]);if k<4{out[k+1]=_mm512_madd52hi_epu64(out[k+1],self.0[i],factor[j]);}}}for i in 0..4{for j in 0..5{let k=i+j;if k>4{continue;}out[k]=_mm512_sub_epi64(out[k],_mm512_madd52lo_epu64(zero,q[i],p[j]));if k<4{out[k+1]=_mm512_sub_epi64(out[k+1],_mm512_madd52hi_epu64(zero,q[i],p[j]));}}}
        let mut carry=zero;for digit in &mut out{let value=_mm512_add_epi64(*digit,carry);*digit=_mm512_and_si512(value,mask);carry=_mm512_srai_epi64::<52>(value);}Self(out,PhantomData)
    }}
}
/// Complete in-place X transform, including packing/stores and scalar tails.
pub fn transform(points:&mut[G2Affine]){let full=points.len()/4*4;for block in points[..full].chunks_exact_mut(4){let input=core::array::from_fn(|i|if i%2==0{block[i/2].x.c0}else{block[i/2].x.c1});let out=Ifma8::<FqConfig,true>::new(&input).mul_inverse_phi_fixed().get();for j in 0..4{block[j].x.c0=out[j*2];block[j].x.c1=out[j*2+1];}}for point in &mut points[full..]{if !point.is_identity(){point.x=point.x.mul_by_fp(&INVERSE_BETA);}}}
#[cfg(test)]mod tests{
use super::*;use crate::{Fr,G2Projective};use ark_ff::{BigInt,PrimeField,Field};
fn ark(x:Fq)->ark_ref::Fq{ark_ref::Fq::from_bigint(BigInt(x.to_canonical())).unwrap()}
fn raw(values:[[u64;4];8])->Ifma8<FqConfig,true>{let columns:[[u64;8];5]=core::array::from_fn(|j|core::array::from_fn(|i|{let bit=j*52;let word=bit/64;let off=bit%64;let mut value=values[i][word]>>off;if off!=0&&word<3{value|=values[i][word+1]<<(64-off);}value&MASK}));unsafe{Ifma8(core::mem::transmute(columns),PhantomData)}}
fn bounds(value:&Ifma8<FqConfig,true>){let columns:[[u64;8];5]=unsafe{core::mem::transmute(value.0)};let p2=crate::portable::add4(FqConfig::P,FqConfig::P).0;for i in 0..8{assert!(columns[4][i]>>48==0);let mut words=[0u64;4];for j in 0..5{assert!(columns[j][i]<=MASK);let bit=j*52;let word=bit/64;let off=bit%64;words[word]|=columns[j][i]<<off;if off!=0&&word<3{words[word+1]|=columns[j][i]>>(64-off);}}assert!(crate::portable::less(words,p2));}}
#[test]fn raw_boundaries_chains_and_arkworks(){assert_eq!(FACTOR,[922702722367486,4251595470861686,233696365179491,24128175338]);assert_eq!(QUOTIENT,[2168209193523166,822091209083389,2454298932930039,2042266689554]);assert_eq!(BETA*BETA,INVERSE_BETA);let p=FqConfig::P;let p2=crate::portable::add4(p,p).0;let mut values=vec![[0;4],[1,0,0,0],p,p2,crate::portable::sub4(p,[1,0,0,0]).0,crate::portable::sub4(p2,[1,0,0,0]).0];for bit in 0..255{let mut w=[0u64;4];w[bit/64]=1<<(bit%64);if crate::portable::less(w,p2){values.push(w);values.push(crate::portable::sub4(w,[1,0,0,0]).0);}}let mut seed=0x29be88c1733a5e91;for _ in 0..4096{let mut w=[0u64;4];for word in &mut w{seed^=seed<<13;seed^=seed>>7;seed^=seed<<17;*word=seed;}while !crate::portable::less(w,p2){w=crate::portable::sub4(w,p2).0;}values.push(w);}let hinv=ark_ref::Fq::from(2u64).pow([256]).inverse().unwrap();let factor=ark(INVERSE_BETA);let mut checked=0;for group in values.chunks(8){let input=core::array::from_fn(|i|group[i%group.len()]);let mut expected=input.map(|words|{let bytes=words.into_iter().flat_map(u64::to_le_bytes).collect::<Vec<_>>();ark_ref::Fq::from_le_bytes_mod_order(&bytes)*hinv});let mut current=raw(input);for _ in 0..8{current=current.mul_inverse_phi_fixed();bounds(&current);let actual=current.get();for i in 0..8{expected[i]*=factor;assert_eq!(ark(actual[i]),expected[i]);checked+=1;}}}eprintln!("INVERSE_PHI_NATIVE_LANES {checked}");}
#[test]fn complete_transforms_tails_and_scalar_correction(){let lambda=Fr::from_decimal("4407920970296243842393367215006156084916469457145843978461");let base=G2Projective::batch_to_affine(&(0..64).map(|i|G2Affine::GENERATOR*Fr::from(i+1)).collect::<Vec<_>>());let inverse=base.iter().map(|p|(*p*lambda.square()).to_affine()).collect::<Vec<_>>();let mut outputs=0;for n in[0usize,1,2,3,4,5,7,8,9,31,63,64,65,511,2048,2049]{let original=(0..n).map(|i|if i%17==0{G2Affine::IDENTITY}else{base[i%64]}).collect::<Vec<_>>();let mut actual=original.clone();let pointer=actual.as_ptr();let capacity=actual.capacity();for pass in 0..3{transform(&mut actual);for i in 0..n{let expected=if original[i].is_identity(){G2Affine::IDENTITY}else{match pass{0=>inverse[i%64],1=>{let mut p=base[i%64];p.x=p.x.mul_by_fp(&BETA);p},_=>original[i]}};assert_eq!(actual[i],expected);outputs+=1;}assert_eq!(actual.as_ptr(),pointer);assert_eq!(actual.capacity(),capacity);}let mut corrected=original.clone();transform(&mut corrected);for p in &mut corrected{if !p.is_identity(){p.x=p.x.mul_by_fp(&BETA);}}assert_eq!(corrected,original);}eprintln!("INVERSE_PHI_POINT_OUTPUTS {outputs}");}
#[test]fn workers_with_small_stacks(){let base=G2Projective::batch_to_affine(&(0..16).map(|i|G2Affine::GENERATOR*Fr::from(i+777)).collect::<Vec<_>>());let mut checked=0;for workers in[1,4,16,32]{let jobs=(0..workers).map(|id|{let original=base.clone();std::thread::Builder::new().name(format!("inverse-phi-{id}")).stack_size(512*1024).spawn(move||{let mut values=original.clone();for _ in 0..3{transform(&mut values);}assert_eq!(values,original);}).unwrap()}).collect::<Vec<_>>();for job in jobs{job.join().unwrap();checked+=1;}}eprintln!("INVERSE_PHI_SMALL_STACK_WORKERS {checked}");}
}
